import java.util.Scanner;
public class DisplayTime2 {
  public static void main(String[] args) {
	//Khutwa 1: Qira'at al-milliseconds
	Scanner scan = new Scanner(System.in);
	System.out.println("Adkhil al-milli-thaniyaat: ");
	long milliSeconds = scan.nextLong();
	scan.close();
	//Khutwa 2: Istikhraj al-saa'at, al-daqayeq wa al-thawani min al-milliseconds
    long totalSecs = milliSeconds / 1000;
    long hours = totalSecs / 3600;
    long mins = (totalSecs / 60) % 60;
    long secs = totalSecs % 60;
    //Khutwa 3: 'Ard al-nateeja
    System.out.println(milliSeconds+" milli-thaniyaat hiya "+hours + " saa'at wa " + mins + " daqayeq wa " + secs + " thawani.");
  }
}
